import {createRoot} from 'react-dom/client';
import {useState,type CSSProperties} from 'react';
import {FinancePage} from '../../components/pages/finance-page';
import {OverviewPage} from '../../components/pages/overview-page';
import {AiPanel} from '../../components/ai-panel';
import {PlanReviewNextStep} from '../../components/plan-review-next-step';
import type {ChatMessage,FinanceResponse} from '../../lib/types';
const finance:FinanceResponse={as_of:'2026-09-30',current:{headcount:10000,fte:9961.2,labor_cost_usd:2047306374.48,cost_per_fte_usd:205528.09,vacant_positions:475,estimated_vacancy_cost_exposure_usd:96300000},by_business_unit:[{org_code:'A',org_name:'Business unit A',headcount:7000,fte:7000,labor_cost_usd:1400000000,cost_per_fte_usd:200000,vacant_positions:450,estimated_vacancy_cost_exposure_usd:90000000,share_of_enterprise_labor_cost_pct:68},{org_code:'B',org_name:'Business unit B',headcount:3000,fte:2961.2,labor_cost_usd:647306374.48,cost_per_fte_usd:218596,vacant_positions:25,estimated_vacancy_cost_exposure_usd:6300000,share_of_enterprise_labor_cost_pct:32}],scenarios:[]};
function Fixture(){
 const [page,setPage]=useState('finance'),[country,setCountry]=useState('US'),[width,setWidth]=useState(500),[input,setInput]=useState(''),[messages,setMessages]=useState<ChatMessage[]>([]),[loading,setLoading]=useState(false);
 const send=(text=input)=>{if(!text.trim()||loading)return;setMessages(current=>[...current,{role:'user',content:text}]);setInput('');setLoading(true);setTimeout(()=>{setMessages(current=>[...current,{role:'assistant',content:'Finance covers the whole company. Review business-unit exposure estimates.'}]);setLoading(false);},1800);};
 return <><header className="flex min-h-16 flex-wrap items-center gap-2 border-b p-2"><label>Country<select aria-label="Country" value={country} onChange={event=>setCountry(event.target.value)}><option value="US">United States</option><option value="all">All countries</option></select></label><button onClick={()=>setPage('workforce')}>Workforce</button><button onClick={()=>setPage('finance')}>Finance</button><button onClick={()=>setWidth(620)}>Widen AI</button></header><div className="app-shell app-ai-left" style={{'--nav-width':'280px','--ai-width':`min(${width}px, max(280px, calc(100vw - var(--nav-width) - 486px)))`,'--divider-width':'6px','--app-header-height':'64px'} as CSSProperties}><aside className="app-sidebar" aria-label="Fixture navigation"/><main className="app-dashboard min-w-0 overflow-x-hidden">{page==='finance'?<FinancePage financeData={finance} financeLoading={false} financeError={null} financeBusinessUnits={finance.by_business_unit} financeScenarios={[]} maxFinanceLaborCost={1400000000}/>:<OverviewPage overviewData={{headcount:5000,fte:4950,labor_cost_usd:1190000000,open_positions:156,voluntary_turnover_ytd_pct:6.2,snapshot_date:'2026-09-30'}} headcountTrend={[]} filterOptions={{countries:[],business_units:[],levels:[]}} selectedCountry={country} selectedOrg="all" selectedLevel="all" selectedCountryLabel={country==='US'?'United States':'All countries'} selectedOrgLabel="All business units" selectedLevelLabel="All levels" dashboardLoading={false} dashboardError={null} filtersActive={country!=='all'} headcountGrowthPct={null} onCountryChange={setCountry} onOrgChange={()=>{}} onLevelChange={()=>{}} onResetFilters={()=>setCountry('all')}/>}
 <section aria-label="Plan next step fixture" className="m-4 rounded border p-3"><PlanReviewNextStep goal="Reduce turnover through a mentoring pilot"/></section></main><AiPanel suppressIntro aiCollapsed={false} aiExpanded={false} aiWidth={width} previewPage={false} suggestedPrompts={['Explain vacancy exposure','Compare labor costs']} scopeNote="Company-wide; selected workforce filters do not apply." chatMessages={messages} chatInput={input} chatLoading={loading} chatError={null} dashboardReady onResizeStart={()=>{}} onResizeKeyDown={()=>{}} onToggleExpanded={()=>setWidth(620)} onToggleCollapsed={()=>{}} onChatInputChange={setInput} onSendSuggested={send} onSend={()=>send()}/></div></>;
}
createRoot(document.getElementById('root')!).render(<Fixture/>);
